import { readFileSync, readdirSync } from 'node:fs';
import { parsePo } from './tools/i18n-engine/dist/index.mjs';
import { segmentMarkdown, collectUnits } from './docs/scripts/segment-markdown.ts';
const locale = 'ar';
const entries = parsePo(readFileSync(`l10n/${locale}/docs.api.po`, 'utf8'));
const translated = new Set(entries.filter((e) => e.msgstr !== '').map((e) => `${e.msgctxt ?? ''}\0${e.msgid}`));
let counts = { glossary: 0, prose: 0, missingGlossary: 0, missingProse: 0 };
for (const file of readdirSync('docs/api', { recursive: true })) {
  if (typeof file !== 'string' || !file.endsWith('.md')) continue;
  const units = collectUnits(segmentMarkdown(readFileSync(`docs/api/${file}`, 'utf8')));
  for (const unit of units) {
    counts[unit.kind]++;
    if (!translated.has(`docs.api:${unit.kind}\0${unit.text}`)) counts[unit.kind === 'glossary' ? 'missingGlossary' : 'missingProse']++;
  }
}
console.log(counts);
